  screening: {
    languages: ['en'],
    fold_accents: true,
    extra_sensitive: [],
    extra_refund: [],
    packs: {
      en: { sensitive: [], refund: [] },
      es: {
        sensitive: ['abogad*', 'demand*', 'fraud*', 'policia', 'accion legal', 'acciones legales', 'proteccion de datos', 'borrar mis datos', 'eliminar mis datos', 'contracargo*', 'filtracion de datos', 'discriminacion', 'denunci*'],
        refund: ['reembols*', 'reintegr*', 'devolucion del dinero', 'devolver el dinero', 'devolveremos el dinero', 'devolvemos el dinero'],
