        sensitive: ['*anwalt*', '*anwaelt*', 'klage', 'klagen', 'verklag*', 'betrug*', 'betrueg*', 'polizei', 'dsgvo', 'datenschutz*', 'meine daten loeschen', 'meine daten löschen', 'datenleck', 'datenpanne', 'diskriminier*', 'rueckbuchung', 'rückbuchung'],
        refund: ['*erstatt*', 'geld zurueck', 'geld zurück', 'rueckzahlung', 'rückzahlung', 'gutschrift*'],
      },
      pt: {
        sensitive: ['advogad*', 'processo judicial', 'processar', 'fraud*', 'policia', 'lgpd', 'protecao de dados', 'apagar meus dados', 'excluir meus dados', 'vazamento de dados', 'discrimina*', 'chargeback', 'acao judicial'],
        refund: ['reembols*', 'estorn*', 'devolver o dinheiro', 'devolveremos o dinheiro', 'devolucao do dinheiro'],
      },
    },
  },

  tools: [
    {
      name: 'order_lookup',
      description: "the customer's own order status and shipping info",
      input: { order_id: { type: 'id' } },
      request: { service: 'ORDER_API_URL', method: 'GET', path: '/orders/{order_id}' },
      owner_field: 'customer_email',
      verifies: 'order_id',
      labels: { not_found: 'order_not_found', unavailable: 'order_service_unavailable' },
    },
    {
      name: 'kb_search',
      description: 'matching help-center articles',
      input: { query: { type: 'text' } },
      request: { service: 'KB_API_URL', method: 'POST', path: '/search', body: { query: '{query}' } },
      result_key: 'results',
      result_limit: 5,
      labels: { unavailable: 'kb_service_unavailable' },
    },
    {
      name: 'refund_check',
      description: 'refund eligibility and amount (only after order_lookup of that order)',
      input: { order_id: { type: 'id' } },
      request: { service: 'REFUND_API_URL', method: 'GET', path: '/refund-eligibility/{order_id}' },
      requires_verified: 'order_id',
      counts_as_refund_check: true,
      labels: { not_found: 'order_not_found', unavailable: 'refund_service_unavailable' },
    },
  ],
};
return [{ json: { ...$input.first().json, playbook } }];

