      for (const t of PB.tools) {
        if (!isObj(t)) { pbErr.push('every tool must be an object'); continue; }
        const w = `tool "${t.name}"`;
        if (typeof t.name !== 'string' || !NAME.test(t.name)) { pbErr.push(`${w}: name must be lowercase letters, digits and _ (2-41 characters)`); continue; }
        if (names.has(t.name)) pbErr.push(`${w}: duplicate name`);
        names.add(t.name);
